}

_choice_ftp_method() {
    printf '%s\n' multicwd nocwd singlecwd
}

_choice_ftp_ssl_ccc_mode() {
    printf '%s\n' active passive
}

_choice_header() {
    if [[ "$ARGC_CWORD" == @* ]]; then
        _argc_util_comp_path prefix=@ filter="${ARGC_CWORD:1}"
        return
    fi
    printf '%s\t%s\n' \
        'Accept:' 'Media types accepted by the client' \
        'Accept-Charset:' 'Character sets accepted' \
        'Accept-Encoding:' 'Content encodings accepted' \
        'Accept-Language:' 'Languages preferred' \
        'Authorization:' 'Authentication credentials' \
        'Cache-Control:' 'Caching directives' \
        'Connection:' 'Connection management options' \
        'Content-Disposition:' 'Presentation of the payload' \
