        'Cookie:' 'Cookie values' \
        'Date:' 'Message date' \
        'Expect:' 'Expected server behavior' \
        'Forwarded:' 'Proxy forwarding information' \
        'Host:' 'Target host and port' \
        'If-Match:' 'Conditional request on ETag' \
        'If-Modified-Since:' 'Conditional request on date' \
        'If-None-Match:' 'Conditional request on ETag' \
        'Origin:' 'Origin of the request' \
        'Pragma:' 'Implementation-specific directives' \
        'Range:' 'Byte range to request' \
        'Referer:' 'Referrer URL' \
