        'X-Forwarded-For:' 'Original client address' \
        'X-Requested-With:' 'Requesting client type'
}

_choice_help() {
    curl --help category 2>/dev/null | gawk 'NF > 1 && $1 !~ /^-/ {
        name = $1
        sub(/^[[:space:]]*[^[:space:]]+[[:space:]]+/, "")
        print name "\t" $0
    }'
}

_choice_interface() {
    command -v ip >/dev/null 2>&1 || return 0
    ip -o link show 2>/dev/null | gawk -F': ' '{ sub(/@.*/, "", $2); print $2 }'
}

_choice_ip_tos() {
    printf '%s\n' CS0 CS1 CS2 CS3 CS4 CS5 CS6 CS7 \
        AF11 AF12 AF13 AF21 AF22 AF23 AF31 AF32 AF33 AF41 AF42 AF43 \
        EF VOICE-ADMIT ECT1 ECT0 CE LE LOWCOST LOWDELAY THROUGHPUT RELIABILITY MINCOST
}

_choice_key_type() {
    printf '%s\n' DER PEM ENG
}

_choice_krb() {
    printf '%s\n' clear safe confidential private
}

_choice_proto() {
    curl --version 2>/dev/null | sed -n 's/^Protocols: //p' | tr ' ' '\n'
}

_choice_request() {
    printf '%s\n' CONNECT DELETE GET HEAD OPTIONS PATCH POST PUT TRACE
}

_choice_tls_max() {
    printf '%s\n' default 1.0 1.1 1.2 1.3
}

_choice_tlsauthtype() {
    printf '%s\n' SRP
}

_choice_trace_config() {
    printf '%s\t%s\n' \
        all 'Enable all trace components' \
        ids 'Add connection ids to trace output' \
        time 'Add timestamps to trace output' |
        _argc_util_comp_multi ,
}

_choice_upload_flags() {
    printf '%s\t%s\n' \
        answered 'Mark message as answered' \
        deleted 'Mark message as deleted' \
        draft 'Mark message as draft' \
        flagged 'Mark message as flagged' \
        seen 'Mark message as seen' \
        | _argc_util_comp_multi ,
}

